/* NABIL Smart Lab Bridge v1
 * One UI/runtime bridge for:
 * - factory lesson concept labs
 * - whole-lesson lab walkthrough
 * - factory exercise cards
 * - general NABIL questions / student chat messages
 * All ad-hoc labs are generated by /api/smart-labs/from-question.
 */
(()=>{
"use strict";
if(window.__NABIL_SMART_LAB_BRIDGE_V1__)return;
window.__NABIL_SMART_LAB_BRIDGE_V1__=true;

const qs=(s,r=document)=>r.querySelector(s);
const qsa=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

function langCode(){
 const htmlLang=String(document.documentElement.lang||"").toLowerCase();
 const selected=String(qs("#languageSelect")?.value||qs("#nabilE2ELanguage")?.value||"").toLowerCase();
 const raw=selected||htmlLang;
 if(/fr|fran/.test(raw))return "fr";
 if(/en|english|anglais/.test(raw))return "en";
 return "ar";
}
function labels(){
 const l=langCode();
 if(l==="fr")return {ask:"🧪 Expliquer avec le laboratoire",whole:"🧪 Expliquer toute la leçon avec les laboratoires",busy:"NABIL construit une simulation vérifiée…",none:"Les données ne suffisent pas pour construire un laboratoire fiable.",close:"Fermer"};
 if(l==="en")return {ask:"🧪 Explain with a lab",whole:"🧪 Explain the whole lesson with labs",busy:"NABIL is building a verified simulation…",none:"The givens are not sufficient for a reliable interactive lab.",close:"Close"};
 return {ask:"🧪 اشرح بالمختبر",whole:"🧪 اشرح الدرس كاملًا بالمختبرات",busy:"نبيل يبني محاكاة موثقة…",none:"المعطيات لا تكفي لبناء مختبر موثوق من دون اختراع.",close:"إغلاق"};
}
function scope(){
 return {
  grade:String(qs("#gradeSelect")?.value||document.querySelector('meta[name="nabil-grade"]')?.content||""),
  subject:String(qs("#subjectSelect")?.value||document.querySelector('meta[name="nabil-subject"]')?.content||""),
  language:langCode()
 };
}
function cleanSource(node){
 if(!node)return "";
 const clone=node.cloneNode(true);
 qsa("button,script,style,.nabil-smart-lab-inline",clone).forEach(n=>n.remove());
 return String(clone.innerText||clone.textContent||"").replace(/\s+/g," ").trim().slice(0,8000);
}
function latestStudentQuestion(){
 const inputs=[qs("#messageInput"),qs("#nabilOpenInput"),qs("#nabilE2EQuestion")];
 for(const input of inputs){
  const value=String(input?.value||"").trim();
  if(value)return value;
 }
 const bubbles=qsa("#chat .message.student .bubble,#chat .message.user .bubble,.message.student .bubble,.message.user .bubble");
 const last=bubbles[bubbles.length-1];
 return cleanSource(last);
}
function ensureModal(){
 let modal=qs("#nabilSmartLabModal");
 if(modal)return modal;
 const style=document.createElement("style");
 style.id="nabilSmartLabBridgeStyle";
 style.textContent=
 "#nabilSmartLabModal[hidden]{display:none!important}#nabilSmartLabModal{position:fixed;inset:0;z-index:2147483600;background:rgba(1,8,17,.88);display:flex;align-items:center;justify-content:center;padding:12px;box-sizing:border-box}"+
 "#nabilSmartLabShell{width:min(1100px,98vw);height:min(860px,94vh);background:#071827;border:1px solid #2de1ff;border-radius:16px;box-shadow:0 24px 80px #000b;display:flex;flex-direction:column;overflow:hidden}"+
 "#nabilSmartLabHead{display:flex;gap:8px;align-items:center;justify-content:space-between;padding:10px 12px;color:#e9fbff;background:#06111f;border-bottom:1px solid #24506f}"+
 "#nabilSmartLabFrame{border:0;width:100%;flex:1;background:#f8fafc}"+
 ".nabil-smart-lab-action{border:1px solid #2dd4bf;background:#0f766e;color:#fff;border-radius:9px;min-height:42px;padding:8px 12px;font:700 13px system-ui;cursor:pointer}"+
 ".nabil-smart-lab-action:disabled{opacity:.55;cursor:wait}.nabil-smart-lab-inline{margin:8px 0;display:flex;gap:8px;flex-wrap:wrap}"+
 ".nabil-solution-runtime-lab{margin-top:12px;border:1px solid #24506f;border-radius:14px;background:#06111f;overflow:hidden}"+
 ".nabil-solution-runtime-lab-head{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:9px 10px;background:#0b2943;color:#dff7ff;font-weight:800}"+
 ".nabil-solution-runtime-lab iframe{display:block;width:100%;height:min(680px,72vh);border:0;background:#05172d}"+
 "@media(max-width:430px){#nabilSmartLabModal{padding:4px}#nabilSmartLabShell{width:100vw;height:100dvh;max-width:none;max-height:none;border-radius:0}#nabilSmartLabHead{padding:8px}#nabilSmartLabFrame{min-height:0}.nabil-smart-lab-action{min-height:44px;font-size:14px}.nabil-solution-runtime-lab iframe{height:66vh}}";
 document.head.appendChild(style);
 modal=document.createElement("div");modal.id="nabilSmartLabModal";modal.hidden=true;
 modal.innerHTML='<div id="nabilSmartLabShell"><div id="nabilSmartLabHead"><strong id="nabilSmartLabTitle">NABIL Smart Lab</strong><button type="button" class="nabil-smart-lab-action" id="nabilSmartLabClose"></button></div><iframe id="nabilSmartLabFrame" title="NABIL Smart Lab" sandbox="allow-scripts allow-same-origin"></iframe></div>';
 document.body.appendChild(modal);
 qs("#nabilSmartLabClose",modal).textContent=labels().close;
 qs("#nabilSmartLabClose",modal).onclick=()=>{modal.hidden=true;const f=qs("#nabilSmartLabFrame",modal);f.srcdoc="";try{window.NABILLessonE2E?.stopSpeech?.()}catch(_e){}};
 modal.addEventListener("click",e=>{if(e.target===modal)qs("#nabilSmartLabClose",modal).click();});
 return modal;
}
function showMessage(text,title="NABIL Smart Lab"){
 const modal=ensureModal();modal.hidden=false;
 qs("#nabilSmartLabTitle",modal).textContent=title;
 qs("#nabilSmartLabFrame",modal).srcdoc='<!doctype html><html dir="'+(langCode()==="ar"?"rtl":"ltr")+'"><meta charset="utf-8"><body style="font-family:system-ui;padding:24px;background:#f8fafc;color:#0f172a"><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></body></html>';
}
async function buildQuestionLab(source,trigger){
 const question=String(source||"").replace(/\s+/g," ").trim();
 if(question.length<3){showMessage(labels().none);return;}
 const old=trigger?.textContent||"";
 if(trigger){trigger.disabled=true;trigger.textContent=labels().busy;}
 try{
  const sc=scope();
  const res=await fetch("/api/smart-labs/from-question",{
   method:"POST",headers:{"Content-Type":"application/json"},
   body:JSON.stringify({question,grade:sc.grade,subject:sc.subject,language:sc.language})
  });
  const data=await res.json().catch(()=>({}));
  if(!res.ok)throw Error(String(data?.detail?.reason||data?.detail||labels().none));
  if(!data.found||!data.html){showMessage(data.reason||labels().none);return;}
  const modal=ensureModal();modal.hidden=false;
  qs("#nabilSmartLabTitle",modal).textContent=data.title||"NABIL Smart Lab";
  qs("#nabilSmartLabFrame",modal).srcdoc=data.html;
 }catch(err){showMessage(String(err?.message||labels().none));}
 finally{if(trigger){trigger.disabled=false;trigger.textContent=old||labels().ask;}}
}

function verifiedSolutionEvidence(result){
 const card=result?.solution_card;
 if(!card||typeof card!=="object")return "";
 const safe={
  subject:card.subject||"",
  title:card.title||"",
  sections:Array.isArray(card.sections)?card.sections:[],
  key_results:Array.isArray(card.key_results)?card.key_results:[],
  verification:Array.isArray(card.verification)?card.verification:[]
 };
 try{return JSON.stringify(safe)}catch(_e){return ""}
}

async function buildInlineQuestionLab(source,card,labKey,result){
 const question=String(source||"").replace(/\s+/g," ").trim();
 if(!card||question.length<3)return;
 if(card.querySelector(".nabil-solution-runtime-lab"))return;
 const holder=document.createElement("section");
 holder.className="nabil-solution-runtime-lab";
 holder.dataset.labKey=String(labKey||"");
 const head=document.createElement("div");head.className="nabil-solution-runtime-lab-head";
 const title=document.createElement("span");title.textContent=langCode()==="ar"?"🧪 المختبر المرتبط بهذا الحل":langCode()==="fr"?"🧪 Laboratoire lié à cette solution":"🧪 Lab linked to this solution";
 const status=document.createElement("span");status.textContent=labels().busy;status.style.fontSize="12px";status.style.color="#b9d7ea";
 head.append(title,status);holder.append(head);card.append(holder);
 try{
   const sc=scope();
   const res=await fetch("/api/smart-labs/from-question",{
     method:"POST",headers:{"Content-Type":"application/json"},
     body:JSON.stringify({question,verified_solution:verifiedSolutionEvidence(result),grade:sc.grade,subject:sc.subject,language:sc.language})
   });
   const data=await res.json().catch(()=>({}));
   if(!res.ok)throw Error(String(data?.detail?.reason||data?.detail||labels().none));
   if(!data.found||!data.html){status.textContent=data.reason||labels().none;return;}
   status.textContent=data.title||"NABIL Smart Lab";
   const frame=document.createElement("iframe");
   frame.title=data.title||"NABIL Smart Lab";
   frame.setAttribute("sandbox","allow-scripts allow-same-origin");
   frame.srcdoc=data.html;
   holder.append(frame);
   card.dataset.nabilLabSource="runtime-question";
   card.dataset.nabilSolutionLabKey=String(labKey||card.dataset.nabilSolutionLabKey||"runtime-question");
 }catch(err){
   status.textContent=String(err?.message||labels().none);
 }
}

function playOneExistingLab(lab){
 if(!lab)return;
 try{window.NABILLessonE2E?.stopSpeech?.()}catch(_e){}
 lab.scrollIntoView({behavior:"smooth",block:"center"});
 setTimeout(()=>lab.dispatchEvent(new CustomEvent("nabil:demo",{bubbles:false})),450);
}
function wireConceptLabs(){
 qsa(".nabil-concept-card").forEach(card=>{
  if(card.dataset.nabilLabButton==="1")return;
  const lab=qs(".interactive-lab",card);
  if(!lab)return;
  card.dataset.nabilLabButton="1";
  const row=document.createElement("div");row.className="nabil-smart-lab-inline";
  const btn=document.createElement("button");btn.type="button";btn.className="nabil-smart-lab-action";btn.textContent=labels().ask;
  btn.onclick=()=>playOneExistingLab(lab);row.appendChild(btn);
  const h=qs("h3",card);if(h)h.insertAdjacentElement("afterend",row);else card.prepend(row);
 });
}
let lessonRunToken=0;
async function playWholeLesson(){
 const whole=qs("#nabilWholeLessonSmartLab");
 const wholePlay=qs("#nabilWholePlay",whole||document);
 if(whole&&wholePlay){
   lessonRunToken++;
   try{window.NABILLessonE2E?.stopSpeech?.()}catch(_e){}
   whole.scrollIntoView({behavior:"smooth",block:"start"});
   setTimeout(()=>wholePlay.click(),420);
   return;
 }
 const labs=qsa(".nabil-concept-card .interactive-lab");
 if(!labs.length){showMessage(labels().none);return;}
 const token=++lessonRunToken;
 for(const lab of labs){
  if(token!==lessonRunToken)return;
  playOneExistingLab(lab);
  const ms=Math.max(2500,Math.min(20000,Number(lab.dataset.demoMs)||6500));
  await new Promise(r=>setTimeout(r,ms));
 }
}
function wireWholeLesson(){
 const btn=qs("#nabilExplainWholeLessonLabs");
 if(btn&&!btn.dataset.nabilWired){btn.dataset.nabilWired="1";btn.textContent=labels().whole;btn.addEventListener("click",playWholeLesson);}
}
function wireExerciseCards(){
 qsa(".nabil-exercise-card").forEach(card=>{
  if(card.dataset.nabilLabWired==="1")return;
  card.dataset.nabilLabWired="1";
  const btn=qs(".nabil-explain-lab-btn",card);
  if(!btn)return;
  const holder=qs(".nabil-prebuilt-exercise-lab",card);
  const prebuilt=holder?qs(".interactive-lab",holder):null;
  if(prebuilt){
   btn.dataset.nabilLabSource="prebuilt";
   btn.addEventListener("click",()=>{
    holder.hidden=false;
    playOneExistingLab(prebuilt);
   });
   return;
  }
  // Factory exercise pages are indexed artifacts. Missing prebuilt lab is a
  // publication defect, never a reason to generate a fresh AI lab per student.
  btn.dataset.nabilLabSource="missing-prebuilt";
  btn.addEventListener("click",()=>showMessage(
    langCode()==="ar"
      ?"هذا التمرين المفهرس لم يصل معه مختبره الجاهز. يجب إعادة نشر الدرس."
      :langCode()==="fr"
        ?"Le laboratoire préconstruit de cet exercice indexé manque. La leçon doit être republiée."
        :"This indexed exercise is missing its prebuilt lab. The lesson must be republished."
  ));
 });
}
function wireLessonQuestionTool(){
 const row=qs("#nabilE2ETools .nabil-e2e-row");
 if(!row||qs("#nabilE2ESmartLab",row))return;
 const btn=document.createElement("button");btn.id="nabilE2ESmartLab";btn.type="button";btn.className="nabil-e2e-btn nabil-smart-lab-action";btn.textContent=labels().ask;
 btn.onclick=()=>buildQuestionLab(latestStudentQuestion(),btn);row.appendChild(btn);
}
function wireMainComposer(){
 if(qs("#nabilMainSmartLabButton"))return;
 const input=qs("#messageInput")||qs("#nabilOpenInput");
 if(!input)return;
 const btn=document.createElement("button");btn.id="nabilMainSmartLabButton";btn.type="button";btn.className="nabil-smart-lab-action";btn.textContent=labels().ask;
 btn.onclick=()=>buildQuestionLab(latestStudentQuestion(),btn);
 const area=input.closest(".input-area,.nabil-open-composer,form")||input.parentElement;
 if(area)area.appendChild(btn);
}
function wireStudentMessages(){
 qsa("#chat .message.student .bubble,#chat .message.user .bubble,.message.student .bubble,.message.user .bubble").forEach(bubble=>{
  if(bubble.dataset.nabilSmartLab==="1")return;
  const source=cleanSource(bubble);if(source.length<3)return;
  bubble.dataset.nabilSmartLab="1";
  const row=document.createElement("div");row.className="nabil-smart-lab-inline";
  const btn=document.createElement("button");btn.type="button";btn.className="nabil-smart-lab-action";btn.textContent=labels().ask;
  btn.onclick=e=>{e.stopPropagation();buildQuestionLab(source,btn);};row.appendChild(btn);
  bubble.appendChild(row);
 });
}
window.addEventListener("nabil:solution-ready",event=>{
 const d=event?.detail||{};
 if(d.mode!=="general_exercises"||!d.card)return;
 buildInlineQuestionLab(d.question,d.card,d.labKey,d.result);
});

function wireAll(){
 wireConceptLabs();wireWholeLesson();wireExerciseCards();wireLessonQuestionTool();wireMainComposer();wireStudentMessages();
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",wireAll,{once:true});else wireAll();
new MutationObserver(()=>wireAll()).observe(document.documentElement,{subtree:true,childList:true});
window.NABILSmartLabs={buildQuestionLab,playWholeLesson,playOneExistingLab};
})();